<script>
  import {onDestroy} from 'svelte';import {client,jobs,trackJob,isAbort,fmt} from '../lib/api.js';import Button from '../components/Button.svelte';import Icon from '../components/Icon.svelte';import Notice from '../components/Notice.svelte';import Select from '../components/Select.svelte';
  export let table;export let lang='vi';let split='test',mode='auto',busy='',error='',alive=true;
  $: t=(vi,en)=>lang==='en'?en:vi;
  $: job=$jobs[table.slug];$: running=job&&['queued','running'].includes(job.status);
  $: result=job?.kind==='evaluate'&&job.status==='done'?job.result:null;
  $: calibrated=job?.kind==='calibrate'&&job.status==='done'?job.result:null;
  const pct=n=>n==null?'—':`${(n*100).toFixed(1)}%`;
  async function run(kind){if(busy||running)return;busy=kind;error='';try{const result=await client.mutate(`${table.slug}:${kind}`,()=>client.request(`/v1/demos/${encodeURIComponent(table.slug)}/${kind}`,{method:'POST',...(kind==='evaluate'?{body:{split,mode}}:{})}));trackJob(table.slug,result.job_id);}catch(e){if(alive&&!isAbort(e))error=e.message;}finally{if(alive)busy='';}}
  onDestroy(()=>alive=false);
</script>
<section class="panel"><h2>{t('Đánh giá chất lượng tìm kiếm','Evaluate search quality')}</h2><p class="text-muted text-sm mt-2 mb-6">{t('Chạy bộ câu hỏi đã chuẩn bị để đo độ đúng và thời gian phản hồi.','Run your prepared questions to measure accuracy and response time.')}</p><div class="flex flex-wrap gap-4 items-end"><div class="field"><span>{t('Bộ dữ liệu','Dataset')}</span><Select bind:value={split} label={t('Bộ dữ liệu','Dataset')} options={[{value:'test',label:'Test'},{value:'dev',label:'Dev'},{value:'all',label:t('Tất cả','All')}]}/></div><div class="field"><span>{t('Chế độ','Mode')}</span><Select bind:value={mode} label={t('Chế độ','Mode')} options={[{value:'auto',label:'Auto'},{value:'fast',label:'Fast'},{value:'accurate',label:'Accurate'}]}/></div><Button variant="primary" busy={busy==='evaluate'} disabled={!!busy||running} on:click={()=>run('evaluate')}><Icon name="chart" size={17}/>{t('Chạy đánh giá','Run evaluation')}</Button><Button busy={busy==='calibrate'} disabled={!!busy||running} on:click={()=>run('calibrate')}>{t('Hiệu chỉnh ngưỡng','Calibrate thresholds')}</Button></div><Notice {error} {lang}/></section>
{#if result}<section class="panel mt-5"><div class="grid grid-cols-2 lg:grid-cols-4 gap-5 mb-6">{#each [['Hit@1',pct(result['hit@1'])],['Hit@3',pct(result['hit@3'])],['MRR',result.mrr?.toFixed(3)||'—'],['P95',`${Math.round(result.latency_ms?.total?.p95||0)} ms`]] as [label,value]}<div class="bg-canvas rounded-lg p-4"><p class="text-xs text-muted mb-2">{label}</p><b class="text-xl">{value}</b></div>{/each}</div><p class="text-muted text-xs">{fmt(result.n_cases)} {t('câu hỏi','questions')} · {t('Đúng trạng thái','Status accuracy')}: {pct(result.status_accuracy)} · {t('Khớp sai','Wrong match')}: {pct(result.matched_wrong_rate)}</p></section>
  {#if result.by_category}<section class="panel mt-5"><h2 class="mb-5">{t('Theo nhóm câu hỏi','By category')}</h2><div class="table-scroll"><table class="data-table"><thead><tr><th>{t('Nhóm','Category')}</th><th>{t('Số câu','Cases')}</th><th>Hit@1</th><th>{t('Đúng trạng thái','Status accuracy')}</th></tr></thead><tbody>{#each Object.entries(result.by_category) as [category,value]}<tr><td>{category}</td><td>{value.n}</td><td>{pct(value['hit@1'])}</td><td>{pct(value.status_acc)}</td></tr>{/each}</tbody></table></div></section>{/if}
  {#if result.suggestions?.length}<section class="panel mt-5"><h2>{t('Gợi ý cải thiện','Improvement suggestions')}</h2>{#each result.suggestions as item}<div class="py-4 border-b border-line"><b>{item.name}</b><p class="text-xs text-muted mt-2">{item.failed_queries?.join('; ')}</p></div>{/each}</section>{/if}
  {#if result.failures?.length}<section class="panel mt-5"><h2 class="mb-5">{result.failures.length} {t('câu chưa đạt','failed cases')}</h2><div class="table-scroll"><table class="data-table"><thead><tr><th>{t('Câu hỏi','Question')}</th><th>{t('Mong đợi','Expected')}</th><th>{t('Thực tế','Actual')}</th></tr></thead><tbody>{#each result.failures as item}<tr><td>{item.query}</td><td>{item.expected_status} {item.expected_ids?.join(', ')}</td><td>{item.status} {item.got_ids?.join(', ')}</td></tr>{/each}</tbody></table></div></section>{/if}
{/if}
{#if calibrated}<section class="panel mt-5"><h2>{t('Đã hiệu chỉnh ngưỡng','Thresholds calibrated')}</h2><pre class="codeblock mt-5">{JSON.stringify(calibrated,null,2)}</pre></section>{/if}
